<div class="card form-card"><form method="post" action="?page=tasks&action=<?=$mode==='create'?'store':'update&id='.$task['id']?>"><?=$csrfField?><div class="form-grid"><label>Project<select name="project_id" required><option value="">Select project</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>" <?=((string)$task['project_id']===(string)$p['id']?'selected':'')?>><?=e($p['name'])?> (<?=e($p['start_date'])?> → <?=e($p['target_date'])?>)</option><?php endforeach;?></select><?php if(isset($errors['project_id'])):?><small class="field-error"><?=e($errors['project_id'])?></small><?php endif;?></label><label>Assignee<select name="assignee_id" required><option value="">Select member</option><?php foreach($members as $m):?><option value="<?=$m['id']?>" <?=((string)$task['assignee_id']===(string)$m['id']?'selected':'')?>><?=e($m['name'])?></option><?php endforeach;?></select><?php if(isset($errors['assignee_id'])):?><small class="field-error"><?=e($errors['assignee_id'])?></small><?php endif;?></label><label>Title<input name="title" required value="<?=e($task['title'])?>"></label><label>Due Date<input type="date" name="due_date" required value="<?=e($task['due_date'])?>"><?php if(isset($errors['due_date'])):?><small class="field-error"><?=e($errors['due_date'])?></small><?php endif;?></label><label>Status<select name="status"><?php foreach(['To Do','In Progress','Done'] as $s):?><option <?=($task['status']===$s?'selected':'')?>><?=$s?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><?php foreach(['Low','Medium','High'] as $s):?><option <?=($task['priority']===$s?'selected':'')?>><?=$s?></option><?php endforeach;?></select></label><label class="full-field">Description<textarea name="description" rows="5" required><?=e($task['description'])?></textarea></label></div><div class="form-actions"><a class="btn" href="?page=tasks">Cancel</a><button class="btn btn-primary">Save</button></div></form></div>
